pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 totalDeposited;
    uint256 totalWithdrawn;

    function setUp() public {
        c = new C(address(this));
        totalDeposited = 0;
        totalWithdrawn = 0;
    }

    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        // Bound amount to a feasible range to avoid overflow and ensure it stays non-zero for the bug to manifest.
        amount = bound(amount, 1, 100 ether);
        // unlockTime can be any timestamp; the fuzzer will explore boundaries.
        unlockTime = bound(unlockTime, 0, type(uint64).max);

        address caller = address(0x1234);
        vm.deal(caller, amount);

        uint256 balanceBefore = address(c).balance;
        uint256 totalBalBefore = totalDeposited - totalWithdrawn;

        // Act: invoke Put with the fuzzed parameters.
        vm.prank(caller);
        c.Put{value: amount}(unlockTime);

        // Track the expected deposits and the expected contract balance.
        totalDeposited += amount;

        // Assert the invariant: the contract's ETH balance must be at least the sum of all
        // net deposits (totalDeposited - totalWithdrawn). Since the mutant never increments
        // contract balance on Put, this will fail for any non-zero amount.
        assertTrue(address(c).balance >= totalDeposited - totalWithdrawn);
    }
}

