contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTime, uint256 warpTime) public {
        // Restrict to admissible domain: amounts must be >= MinSum (1 ether) and <= balance,
        // warpTime represents the timestamp at which Collect is attempted.
        uint256 minSum = 1 ether;
        vm.assume(amount >= minSum && amount <= 100 ether);
        vm.assume(unlockTime > 0 && unlockTime <= type(uint64).max);
        vm.assume(warpTime >= 0 && warpTime <= type(uint64).max);

        address actor = address(0x1234);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // Advance time to warpTime
        vm.warp(warpTime);

        bool ok;
        vm.prank(actor);
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: If Collect succeeds, then warpTime (block.timestamp) must be > unlockTime.
        // This holds in the reference C, but the mutant breaks it by allowing success when warpTime <= unlockTime.
        assertTrue(!ok || warpTime > unlockTime);
    }
}

