pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 collectAmount) public {
        // Bound amounts to reasonable ranges to avoid overflow in fuzzer arithmetic
        uint256 minSum = c.MinSum();
        bound(amount, minSum, type(uint128).max / 2);
        bound(collectAmount, 1, amount);

        // Setup a user account
        address user = address(0x1234);
        vm.deal(user, amount);

        // User puts funds with unlockTime far in the future
        vm.prank(user);
        c.Put{value: amount}(block.timestamp + 365 days);

        // Warp to a time before the unlock time
        vm.warp(block.timestamp + 1 days);

        // Record contract balance before collect
        uint256 contractBalanceBefore = address(c).balance;

        // Attempt to collect - this should fail in reference, succeed in mutant
        bool ok;
        vm.prank(user);
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // If collect succeeded, check invariant: contract balance >= user balance + minSum
        // For reference contract, collect should fail (ok == false), making invariant vacuously true
        // For mutant contract, collect can succeed when it shouldn't, breaking the invariant
        if (ok) {
            uint256 userBalanceAfter = c.Acc(user);
            assertTrue(
                address(c).balance >= userBalanceAfter + minSum,
                "INVARIANT BROKEN: contract balance must be >= user balance + minSum after successful collect"
            );
        } else {
            // If collect failed, contract balance should be unchanged
            assertEq(address(c).balance, contractBalanceBefore);
        }
    }
}

